#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <csignal>

// Global synchronization primitives for the waiting threads
class ThreadBomb {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::thread> threads;
    volatile bool running = true;

public:
    // Target function that waits on a condition variable forever
    void wait_forever() {
        std::unique_lock<std::mutex> lock(mtx);
        // Wait for a condition that will never be true
        cv.wait(lock, []{ return false; });
    }

    // Signal handler to allow graceful shutdown with Ctrl+C
    static void signal_handler(int signal) {
        std::cout << "\nReceived signal " << signal << ", stopping thread creation..." << std::endl;
        // In a real implementation, we'd set a flag here to stop the loop
        // For now, we just let it break naturally when join fails
    }

    // Create and start threads until we hit system limits
    void create_threads_until_limit() {
        // Set up signal handling for clean interruption
        std::signal(SIGINT, signal_handler);
        std::signal(SIGTERM, signal_handler);

        size_t count = 0;

        std::cout << "Starting thread creation... Press Ctrl+C to stop." << std::endl;

        while (running) {
            try {
                // Create a new thread that waits forever on the condition variable
                threads.emplace_back(&ThreadBomb::wait_forever, this);

                ++count;

                // Progress output every 100 threads
                if (count % 100 == 0) {
                    std::cout << "Created " << count << " threads so far..." << std::endl;
                }

            } catch (const std::system_error& e) {
                std::cout << "\nFailed to create thread #" << (count + 1) << ": " << e.what() << std::endl;
                std::cout << "This usually means we've hit a system limit." << std::endl;
                break;
            } catch (const std::exception& e) {
                std::cout << "\nUnexpected error creating thread: " << e.what() << std::endl;
                break;
            }
        }

        std::cout << "\n=== Thread Creation Summary ===" << std::endl;
        std::cout << "Total threads created: " << count << std::endl;

        // Try to get system information about thread limits
        std::cout << "\nChecking system limits..." << std::endl;

        // Execute shell commands to get limit information
        std::system("echo 'System-wide threads-max:'; cat /proc/sys/kernel/threads-max 2>/dev/null || echo 'Not available'");
        std::system("echo 'Per-process limit (RLIMIT_NPROC):'; ulimit -u 2>/dev/null || echo 'Not available'");
        std::system("echo 'Available processors:'; nproc --all 2>/dev/null || echo 'Not available'");

        std::cout << "\nNOTE: The actual limit encountered may be due to memory constraints,"
                  << "\nas each thread requires stack space (typically 8MB by default)." << std::endl;

        // Don't join the threads (they would never terminate)
        // In production code, you'd want proper cleanup, but here we're demonstrating the limit
    }

    // Clean up all threads (not called in this example as they wait forever)
    void cleanup() {
        running = false;
        cv.notify_all(); // Won't actually wake them due to predicate, but good practice

        // Join only threads that are joinable
        for (auto& t : threads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }
};

int main() {
    ThreadBomb bomb;
    bomb.create_threads_until_limit();

    // Note: We don't call cleanup() here as we want to demonstrate the limit
    // The program will exit, and the OS will clean up the threads

    return 0;
}

#include <iostream>
#include <thread>
#include <vector>
#include <chrono>
#include <mutex>
#include <condition_variable>
#include <fstream>
#include <sstream>
#include <string>
#include <cstdlib>

// Global synchronization primitives
std::mutex mtx;
std::condition_variable cv;
std::vector<std::thread> threads;
volatile bool stop_observing = false;

/**
 * Target function that waits on a condition variable forever.
 * This creates a parked thread that consumes a thread handle but minimal CPU.
 */
void wait_forever() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, []{ return false; });
}

/**
 * Execute a shell command and return its output as a string.
 */
std::string exec_command(const char* cmd) {
    std::array<char, 128> buffer;
    std::string result;
    std::unique_ptr<FILE, decltype(&pclose)> pipe(popen(cmd, "r"), pclose);

    if (!pipe) {
        return "popen() failed!";
    }

    while (fgets(buffer.data(), buffer.size(), pipe.get()) != nullptr) {
        result += buffer.data();
    }

    return result;
}

/**
 * Collect scheduler and system metrics.
 */
struct Metrics {
    long long timestamp_ms;
    int thread_count;
    double load_avg_1;
    double load_avg_5;
    double load_avg_15;
    int tasks_running;
    int tasks_sleeping;
    std::string str() const {
        std::ostringstream oss;
        oss << timestamp_ms << "," 
            << thread_count << "," 
            << load_avg_1 << "," 
            << load_avg_5 << "," 
            << load_avg_15 << "," 
            << tasks_running << "," 
            << tasks_sleeping;
        return oss.str();
    }
};

/**
 * Parse /proc/loadavg to get system load and task counts.
 */
bool get_loadavg(double& load1, double& load5, double& load15, int& running, int& total) {
    std::ifstream file("/proc/loadavg");
    if (!file.is_open()) {
        return false;
    }

    std::string line;
    std::getline(file, line);
    file.close();

    std::istringstream iss(line);
    std::string temp;

    // Read load averages
    if (!(iss >> load1 >> load5 >> load15)) return false;

    // Skip the next field (5th field)
    if (!(iss >> temp)) return false;

    // Read the 6th field: running/total tasks
    std::string task_field;
    if (!(iss >> task_field)) return false;

    size_t slash_pos = task_field.find('/');
    if (slash_pos == std::string::npos) return false;

    running = std::stoi(task_field.substr(0, slash_pos));
    // 'total' is not collected here as it's less relevant

    return true;
}

/**
 * Observer function that periodically collects system metrics.
 */
void observe_scheduler(int interval_ms) {
    std::ofstream data_file("scheduler_data.csv");

    // Write CSV header
    data_file << "timestamp_ms,created_threads,load_avg_1,load_avg_5,load_avg_15,tasks_running,tasks_sleeping\n";

    auto start_time = std::chrono::steady_clock::now();

    while (!stop_observing) {
        auto now = std::chrono::steady_clock::now();
        auto elapsed_ms = std::chrono::duration_cast<std::chrono::milliseconds>(now - start_time).count();

        // Get current number of created threads
        int current_thread_count = threads.size();

        // Get load average and task info
        double load1 = 0, load5 = 0, load15 = 0;
        int running_tasks = 0, total_tasks = 0;

        if (get_loadavg(load1, load5, load15, running_tasks, total_tasks)) {
            // Estimate sleeping tasks from top output
            std::string top_output = exec_command("top -b -n 1 -H | grep \"KiB Swap\" -A 100 | tail -n +3 | awk '{print $2}' | sort | uniq -c | awk '{print $1}' | paste -sd+ | bc 2>/dev/null || echo 0");
            int sleeping_tasks = 0;
            try {
                sleeping_tasks = std::stoi(top_output);
            } catch (...) {
                sleeping_tasks = 0;
            }

            // Create and write metrics
            Metrics m;
            m.timestamp_ms = elapsed_ms;
            m.thread_count = current_thread_count;
            m.load_avg_1 = load1;
            m.load_avg_5 = load5;
            m.load_avg_15 = load15;
            m.tasks_running = running_tasks;
            m.tasks_sleeping = sleeping_tasks;

            data_file << m.str() << "\n";
            data_file.flush();

            // Print summary to console
            std::cout << "[" << (elapsed_ms/1000.0) << "s] Threads: " << current_thread_count 
                      << ", Load: " << load1 << ", Running/Sleeping: " << running_tasks << "/" << sleeping_tasks << std::endl;
        }

        // Wait for next interval
        std::this_thread::sleep_for(std::chrono::milliseconds(interval_ms));
    }

    data_file.close();
    std::cout << "Scheduler observation completed. Data saved to scheduler_data.csv" << std::endl;
}

/**
 * Create threads until we hit system limits.
 */
void create_threads_until_limit(int observer_interval_ms) {
    // Start the observer thread first
    std::thread observer_thread(observe_scheduler, observer_interval_ms);

    size_t count = 0;
    const int progress_interval = 100;

    std::cout << "Starting thread creation with scheduler observation..." << std::endl;

    while (!stop_observing) {
        try {
            // Create a new thread that waits forever
            threads.emplace_back(wait_forever);
            ++count;

            // Periodic update
            if (count % progress_interval == 0) {
                std::cout << "Created " << count << " threads..." << std::endl;
            }

        } catch (const std::system_error& e) {
            std::cout << "\nFailed to create thread #" << (count + 1) << ": " << e.what() << std::endl;
            std::cout << "This usually means we've hit a system limit." << std::endl;
            stop_observing = true;
            break;
        } catch (const std::exception& e) {
            std::cout << "\nUnexpected error creating thread: " << e.what() << std::endl;
            stop_observing = true;
            break;
        }
    }

    // Stop the observer
    stop_observing = true;

    // Wait for observer to finish
    if (observer_thread.joinable()) {
        observer_thread.join();
    }

    std::cout << "\n=== Final Summary ===" << std::endl;
    std::cout << "Total threads created: " << count << std::endl;

    // Report system limits
    std::system("echo 'System-wide threads-max:'; cat /proc/sys/kernel/threads-max 2>/dev/null || echo 'Not available'");
    std::system("echo 'Per-process limit (RLIMIT_NPROC):'; ulimit -u 2>/dev/null || echo 'Not available'");
    std::system("echo 'Available processors:'; nproc --all 2>/dev/null || echo 'Not available'");

    // Don't join worker threads (they would never terminate)
}

int main() {
    // Set smaller stack size to allow more threads (optional)
    // This would require pthread attributes, omitted for simplicity

    create_threads_until_limit(2000); // Observe every 2 seconds

    return 0;
}

